mapper.select:
SELECT COUNT(0) FROM department WHERE 1 = 1
AND name LIKE CONCAT('%', #{name}, '%')
AND parent_id = #{parentId}

WITH dept AS ( SELECT d.id AS id, d.name AS name, d.parent_id AS parentId, fp.id AS fullpath, d.leader AS leader, DATE_FORMAT(d.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt, DATE_FORMAT(d.updated_at, '%Y-%m-%d %H:%i:%s') AS updatedAt, DATE_FORMAT(d.deleted_at, '%Y-%m-%d %H:%i:%s') AS deletedAt FROM department d, JSON_TABLE( d.fullpath, '$[*]' COLUMNS (id varchar(255) PATH '$') ) fp WHERE JSON_LENGTH(d.fullpath) > 0
AND name LIKE CONCAT('%', #{name}, '%')
AND parent_id = #{parentId}
UNION SELECT d.id AS id, d.name AS name, d.parent_id AS parentId, NULL AS fullpath, d.leader AS leader, DATE_FORMAT(d.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt, DATE_FORMAT(d.updated_at, '%Y-%m-%d %H:%i:%s') AS updatedAt, DATE_FORMAT(d.deleted_at, '%Y-%m-%d %H:%i:%s') AS deletedAt FROM department d WHERE JSON_LENGTH(d.fullpath) = 0
AND name LIKE CONCAT('%', #{name}, '%')
AND parent_id = #{parentId}
) SELECT * FROM dept ORDER BY id DESC LIMIT #{pageSize} OFFSET #{current}

SELECT COUNT(0) FROM team_member WHERE 1 = 1
AND team_id = #{teamId}
AND username LIKE CONCAT('%', #{username}, '%')

