UPDATE
    team
SET
    id = #{teamInfo.id}

    ,name = #{teamInfo.name}


    ,avatar_url = #{teamInfo.avatarUrl}


    ,description = #{teamInfo.description}


    ,invite_link = #{teamInfo.inviteLink}


    ,invite_expiration = STR_TO_DATE(#{teamInfo.inviteExpiration}, '%Y-%m-%d %H:%i:%s')


    ,invite_approve = #{teamInfo.inviteApprove}

WHERE
    id = #{teamInfo.id}
    AND id IN (
        SELECT
            team_id
        FROM
            team_member
        WHERE
            team_id = #{teamInfo.id}
            AND user_id = #{userId}
            AND is_admin > 0
    )

UPDATE
    team
SET
    owner_id = #{newOwnerId}
WHERE
    id = #{Id}
    AND owner_id = #{oldOwnerId}

