mapper.insert:
INSERT INTO team_member ( team_id, user_id, username, is_admin,
pending,
created_at ) VALUES ( #{teamId}, #{userId}, #{username}, #{isAdmin},
#{pending},
CURRENT_TIMESTAMP ) ON DUPLICATE KEY UPDATE username = #{username} ,is_admin = #{isAdmin}
,pending = #{pending}

mapper.update:
UPDATE
    team_member utm
SET
    utm.is_admin = #{isAdmin}

    ,utm.username = #{username}

WHERE
    utm.team_id = #{teamId}
    AND utm.user_id = #{userId}
    AND EXISTS (
        SELECT
            1
        FROM (
            SELECT
                *
            FROM
                team_member
            WHERE
                user_id = #{loginUserId}
                AND is_admin > 0
        ) ctm
        WHERE
            utm.team_id = ctm.team_id
    )

UPDATE team_member utm SET utm.pending = NULL WHERE utm.team_id = #{teamId} AND utm.user_id = #{approvedUserId}
AND utm.is_admin <= 1
AND EXISTS ( SELECT 1 FROM ( SELECT * FROM team_member WHERE user_id = #{approverUserId} AND is_admin > 0 ) ctm WHERE utm.team_id = ctm.team_id )

mapper.delete:
DELETE FROM team_member utm WHERE utm.team_id = #{teamId} AND utm.user_id = #{notApprovedOrRemoveUserId}
AND utm.is_admin <= 1
AND EXISTS ( SELECT 1 FROM ( SELECT * FROM team_member WHERE user_id = #{approverUserId} AND is_admin > 0 ) ctm WHERE utm.team_id = ctm.team_id )
